parameters.jsCode:
const CODE_VERSION = "booking_action_prepare_v1";

const body = $json.body || $json;
const message = body.message || {};

const toolCall =
  message.toolCalls?.[0] ||
  message.toolCallList?.[0] ||
  message.toolWithToolCallList?.[0]?.toolCall ||
  $json.toolCalls?.[0] ||
  $json.toolCallList?.[0] ||
  null;

if (!toolCall) {
  throw new Error("No tool call found");
}

const toolCallId = toolCall.id;
const toolName = toolCall.function?.name || "";

let args = toolCall.function?.arguments || {};

if (typeof args === "string") {
  try {
    args = JSON.parse(args);
  } catch (error) {
    throw new Error("Could not parse tool arguments: " + toolCall.function?.arguments);
  }
}

if (!args || Object.keys(args).length === 0) {
  throw new Error(
    `${toolName} was called with empty arguments. Check Vapi tool schema, Strict mode, and make sure the assistant was published after updating the tool.`
  );
}

function getTimezoneOffsetFromIso(isoString) {
  const match = String(isoString || "").match(/([+-]\d{2}:\d{2}|Z)$/);

  if (!match) {
    throw new Error(
      "new_appointment_start must include timezone, example: 2026-05-27T14:00:00+03:00"
    );
  }

  return match[1];
}

function offsetToMinutes(offset) {
  if (offset === "Z") return 0;

  const sign = offset.startsWith("+") ? 1 : -1;
  const [hours, minutes] = offset.slice(1).split(":").map(Number);

  return sign * ((hours * 60) + minutes);
}

function formatWithOffset(date, offset) {
  const offsetMinutes = offsetToMinutes(offset);
  const localTime = new Date(date.getTime() + offsetMinutes * 60 * 1000);
  const datePart = localTime.toISOString().slice(0, 19);

  if (offset === "Z") {
    return `${datePart}Z`;
  }

  return `${datePart}${offset}`;
}

function addOneHourKeepingOffset(isoString) {
  const offset = getTimezoneOffsetFromIso(isoString);
  const start = new Date(isoString);

  if (isNaN(start.getTime())) {
    throw new Error("Invalid new_appointment_start: " + isoString);
  }

  const end = new Date(start.getTime() + 60 * 60 * 1000);

  return formatWithOffset(end, offset);
}

const actionType =
  toolName === "reschedule_booking"
    ? "reschedule"
    : toolName === "cancel_booking"
      ? "cancel"
      : "unknown";

if (actionType === "unknown") {
  throw new Error("Unsupported booking action tool: " + toolName);
}

const calendarEventId = args.calendar_event_id || args.booking_id || "";

if (!calendarEventId) {
  throw new Error("Missing calendar_event_id");
}

let output = {
  code_version: CODE_VERSION,

  tool_name: toolName,
  action_type: actionType,
  tool_call_id: toolCallId,

  calendar_event_id: calendarEventId
};

if (actionType === "reschedule") {
  if (!args.new_appointment_start) {
    throw new Error("Missing new_appointment_start");
  }

  if (!args.new_appointment_time_label) {
    throw new Error("Missing new_appointment_time_label");
  }

  const newAppointmentEnd = addOneHourKeepingOffset(args.new_appointment_start);

  output = {
    ...output,

    new_appointment_start: args.new_appointment_start,
    new_appointment_end: newAppointmentEnd,
    new_appointment_time_label: args.new_appointment_time_label
  };
}

if (actionType === "cancel") {
  output = {
    ...output,

    cancellation_reason: args.cancellation_reason || "",
    old_appointment_time_label: args.old_appointment_time_label || ""
  };
}

return [
  {
    json: output
  }
];

