const prep = $('Prepare Booking Action Data').item.json;

const message = `You’re all set. Your appointment has been rescheduled to ${prep.new_appointment_time_label}, and I’ve sent the updated confirmation email. Is there anything else I can help you with today?`;

return [
  {
    json: {
      results: [
        {
          toolCallId: prep.tool_call_id,
          result: message
        }
      ]
    }
  }
];

